type StopInput = Partial<GuideStop> & {
  id: string;
  poiId: string;
  name: string;
  coordinates: [number, number];
  description: string;
  sourcePhoto: string;
  officialUrl: string;
  mapQuery?: string;
  editorialUrls?: string[];
  platformUrls?: string[];
};

function stop(input: StopInput): GuideStop {
  const {
    id,
    poiId,
    name,
    coordinates,
    description,
    sourcePhoto,
    officialUrl,
    mapQuery,
    editorialUrls = [],
    platformUrls = [],
    sourceEvidence,
    bookingUrl,
    ...rest
  } = input;
  const mapUrl = sourceEvidence?.mapUrl ?? maps(mapQuery ?? `${name} Singapore`);
  const sourceUrls = [officialUrl, mapUrl, sourcePhoto, ...editorialUrls, ...platformUrls, ...(input.sourceUrls ?? [])];

  return {
    id,
    poiId,
    name,
    coordinates,
    description,
    photo: sourcePhoto,
    imageSourceUrl: sourcePhoto,
    imageSourceName: sourcePhoto.includes("wikimedia.org") ? "Wikimedia Commons" : "Official/property media",
    sourceUrls: [...new Set(sourceUrls)],
    sourceEvidence: {
      officialUrl,
      mapUrl,
      currentStatusUrl: mapUrl,
      imageSourceUrl: sourcePhoto,
      editorialUrls,
      platformUrls,
      checkedAt,
      notes: "Official/property schedule and current map listing checked for active status; no permanent-closure warning remained in the accepted source set.",
      ...sourceEvidence,
    },
    officialUrl,
    ...(bookingUrl ? { bookingUrl } : {}),
    ...rest,
  };
}

